function ahoBuild(patterns){
  var root={children:{}, fail:null, out:[]};
  patterns.forEach(function(p, idx){
    if(p.length===0) return;
    var node=root;
    for(var i=0;i<p.length;i++){
      var c=p[i];
      if(!node.children[c]) node.children[c]={children:{}, fail:null, out:[]};
      node=node.children[c];
    }
    node.out.push({pattern:p, index:idx});
  });
  var queue=[];
  for(var key in root.children){ var ch=root.children[key]; ch.fail=root; queue.push(ch); }
  while(queue.length){
    var cur=queue.shift();
    for(var k in cur.children){
      var child=cur.children[k];
      var f=cur.fail;
      while(f!==null && !f.children[k]) f=f.fail;
      child.fail = f!==null ? f.children[k] : root;
      child.out = child.out.concat(child.fail.out);
      queue.push(child);
    }
  }
  return root;
}
function ahoFind(text, root){
  var res=[];
  var node=root;
  for(var i=0;i<text.length;i++){
    var c=text[i];
    while(node!==null && !node.children[c]) node=node.fail;
    if(node===null) node=root;
    node = node.children[c] || root;
    for(var j=0;j<node.out.length;j++){
      var o=node.out[j];
      res.push({pattern:o.pattern, index:i - o.pattern.length + 1});
    }
  }
  return res;
}
if (typeof module !== 'undefined' && module.exports) {
  module.exports = { ahoBuild:ahoBuild, ahoFind:ahoFind };
}
if (typeof window !== 'undefined') {
  window.AhoForgePure = { ahoBuild:ahoBuild, ahoFind:ahoFind };
}
